UPDATE user
nickname = #{nickname}, avatar = #{avatar}, sign = #{sign}, phone = #{phone}, email = #{email}, password = #{password}, status = #{status}, level = #{level}, exp = #{exp}, real_name_verified = #{realNameVerified}, coin_count = #{coinCount},
