UPDATE user
SET like_total = GREATEST(0, like_total + #{increment})
WHERE id = #{userId}

UPDATE user
SET follow_count = GREATEST(0, follow_count + #{increment})
WHERE id = #{userId}

UPDATE user
SET fans_count = GREATEST(0, fans_count + #{increment})
WHERE id = #{userId}

